export function selectionHandles(o){if(o.type==='GuideObject')return [{key:'centre',point:localToWorld({x:0,y:0},o)},{key:'rotate',point:localToWorld({x:150,y:0},o)}];const b=bounds(o);return [[0,0],[.5,0],[1,0],[1,.5],[1,1],[.5,1],[0,1],[0,.5]].map(([x,y],i)=>({key:i,point:localToWorld({x:b.x+b.w*x,y:b.y+b.h*y},o)})).concat([{key:'centre',point:localToWorld({x:b.x+b.w/2,y:b.y+b.h/2},o)}])}
